para.programlisting:
rand("seed", 0);
X1 = rand(20, 2);
X2 = rand(20, 2) + [3 0];
X3 = rand(20, 2) + [1.5 3];

X = [X1; X2; X3];
labels = [ones(20, 1); 2 * ones(20, 1); 3 * ones(20, 1)];

// compute the silhouette coefficients
s = silhouette(X, labels);
s(1:5)

// compute the score (average) silhouette
m = mean(s)

rand("seed", 0);
data = [rand(30, 2) + 1; rand(30, 2) + 5; rand(30, 2) + 9];
idx = kmeans(data, 3);
s = silhouette(data, idx);
s(1:5)
